sys_script_include.script:
var RescheduleEventUtils = Class.create();
RescheduleEventUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
	reschedule: function() {
		var _recordSysId = this.getParameter('sysparm_sys_id');
		var _newDate = this.getParameter('sysparm_new_date');

		var _eventGR = new GlideRecord('x_1790139_event_ma_event_record');
		if(_eventGR.get(_recordSysId)) {
			_eventGR.x_event_date = _newDate;
			_eventGR.update();

			gs.eventQueue('x_1790139_event_ma.event.rescheduled', _eventGR, _eventGR.x_assigned_planner.email, '');
		}
	},
    type: 'RescheduleEventUtils'
});
